INSERT INTO boards (board_id, workspace_id, name, payload, router_time, time_basis, origin_installation, origin_machine, import_digest) VALUES (json_extract(?1, '$.record.envelope.id'), json_extract(?1, '$.record.workspaceId'), json_extract(?1, '$.record.name'), ?1, ?2, ?3, ?4, ?5, ?6) ON CONFLICT(board_id) DO UPDATE SET workspace_id = excluded.workspace_id, name = excluded.name, payload = excluded.payload, router_time = excluded.router_time, time_basis = excluded.time_basis, origin_installation = excluded.origin_installation, origin_machine = excluded.origin_machine, import_digest = coalesce(boards.import_digest, excluded.import_digest);
